package com.pandinila.broadband_management.config;
import com.pandinila.broadband_management.entity.*;import com.pandinila.broadband_management.repository.*;import org.springframework.boot.CommandLineRunner;import org.springframework.context.annotation.*;
@Configuration public class SampleDataConfig {@Bean CommandLineRunner sampleData(CustomerRepository customers,SupportTeamRepository teams,EngineerRepository engineers){return args->{if(customers.count()>0)return;String[] names={"Aarav Sharma","Diya Patel","Vihaan Reddy","Ananya Singh","Arjun Kumar","Isha Nair","Kabir Mehta","Meera Iyer","Rohan Das","Sana Khan","Aditya Rao","Kavya Joshi","Reyansh Gupta","Nisha Verma","Ishaan Bose","Priya Menon","Ayaan Shah","Tanvi Kapoor","Dev Malhotra","Riya Jain"};for(int i=0;i<names.length;i++){Customer c=new Customer();c.setCustomerId("CUST%03d".formatted(i+1));c.setName(names[i]);c.setEmail("customer"+(i+1)+"@demo.local");c.setPhone("900000%04d".formatted(i+1));c.setCity(i%2==0?"Chennai":"Bengaluru");c.setAddress("Demo address "+(i+1));c.setServicePlan(i%3==0?"Fiber 200 Mbps":"Fiber 100 Mbps");c.setConnectionType("FTTH");c.setPreviousComplaintCount(i%10>8?4:i%10>6?1:0);customers.save(c);}String[] teamNames={"Network Operations Team","Broadband Support Team","Fiber Operations Team","Field Engineering Team","Network Monitoring Team"};for(String n:teamNames){SupportTeam t=new SupportTeam();t.setName(n);t.setDescription("Demo support team");teams.save(t);}for(int i=0;i<5;i++){Engineer e=new Engineer();e.setEngineerId("ENG%03d".formatted(i+1));e.setName("Engineer "+(i+1));e.setEmail("engineer"+(i+1)+"@demo.local");e.setSpecialization(i%2==0?"Network diagnostics":"Fiber operations");e.setTeam(teams.findAll().get(i));engineers.save(e);}};}}
